/**
 * Diff Extension
 *
 * /diff command shows modified/deleted/new files from git status and opens
 * the selected file in VS Code's diff view.
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";

export default function (pi: ExtensionAPI) {
	pi.registerCommand("diff", {
		description: "Show git changes and open in VS Code diff view",
		handler: async (_args, ctx) => {
			if (!ctx.hasUI) {
				ctx.ui.notify("No UI available", "error");
				return;
			}

			// Get changed files from git status
			const result = await pi.exec("git", ["status", "--porcelain"], { cwd: ctx.cwd });

			if (result.code !== 0) {
				ctx.ui.notify(`git status failed: ${result.stderr}`, "error");
				return;
			}

			if (!result.stdout.trim()) {
				ctx.ui.notify("No changes in working tree", "info");
				return;
			}

			// Parse git status output
			// Format: XY filename (where XY is two-letter status)
			const lines = result.stdout.trim().split("\n");
			const files: { status: string; file: string; display: string }[] = [];

			for (const line of lines) {
				if (!line.trim()) continue;

				const status = line.substring(0, 2);
				const file = line.substring(3);

				// Translate status codes to human readable
				let statusLabel: string;
				if (status.includes("M")) statusLabel = "modified";
				else if (status.includes("A")) statusLabel = "added";
				else if (status.includes("D")) statusLabel = "deleted";
				else if (status.includes("?")) statusLabel = "untracked";
				else if (status.includes("R")) statusLabel = "renamed";
				else if (status.includes("C")) statusLabel = "copied";
				else statusLabel = status.trim() || "changed";

				files.push({
					status: statusLabel,
					file,
					display: `[${statusLabel}] ${file}`,
				});
			}

			if (files.length === 0) {
				ctx.ui.notify("No changes found", "info");
				return;
			}

			// Show file picker
			const choices = files.map((f) => f.display);
			const selected = await ctx.ui.select("Select file to diff:", choices);

			if (!selected) return;

			// Find the selected file
			const selectedFile = files.find((f) => f.display === selected);
			if (!selectedFile) return;

			// Open in VS Code diff view (this will block until VS Code is closed)
			// For untracked files, git difftool won't work, so fall back to just opening the file
			if (selectedFile.status === "untracked") {
				await pi.exec("code", ["-g", selectedFile.file], { cwd: ctx.cwd });
			} else {
				const diffResult = await pi.exec(
					"git",
					["difftool", "-y", "--tool=vscode", selectedFile.file],
					{ cwd: ctx.cwd }
				);
				// Fallback if difftool fails
				if (diffResult.code !== 0) {
					await pi.exec("code", ["-g", selectedFile.file], { cwd: ctx.cwd });
				}
			}
		},
	});
}

