```python
"""
Runtime type-hint validation decorator.
"""

from __future__ import annotations

import functools
import inspect
from typing import Any, Union, get_args, get_origin, get_type_hints


def _is_optional(tp: type) -> bool:
    """Check if a type is Optional[X] (Union[X, None])."""
    return get_origin(tp) is Union and type(None) in get_args(tp)


def _validate(value: Any, expected_type: Any, arg_name: str) -> None:
    """Recursively validate *value* against *expected_type*."""
    if expected_type is Any or isinstance(expected_type, str):
        return

    if value is None:
        if _is_optional(expected_type) or expected_type is type(None):
            return
        raise TypeError(f"Argument '{arg_name}' expected {expected_type}, got None")

    origin = get_origin(expected_type)

    # Union / Optional
    if origin is Union:
        for sub in get_args(expected_type):
            try:
                _validate(value, sub, arg_name)
                return
            except TypeError:
                continue
        raise TypeError(f"Argument '{arg_name}' expected {expected_type}, got {type(value).__name__}")

    # Generic containers: list, dict, tuple, set
    if origin is not None:
        container_checks = {list: list, dict: dict, tuple: tuple, set: set, frozenset: frozenset}
        concrete = container_checks.get(origin, origin)
        if not isinstance(value, concrete):
            raise TypeError(f"Argument '{arg_name}' expected {expected_type}, got {type(value).__name__}")

        args = get_args(expected_type)
        if origin is list or origin is set or origin is frozenset:
            et = args[0] if args else Any
            for i, item in enumerate(value):
                _validate(item, et, f"{arg_name}[{i}]")
        elif origin is dict:
            kt = args[0] if args else Any
            vt = args[1] if len(args) > 1 else Any
            for k, v in value.items():
                _validate(k, kt, f"{arg_name}[key={k!r}]")
                _validate(v, vt, f"{arg_name}[{k!r}]")
        elif origin is tuple:
            if args and args[-1] is not ...:         # fixed-length
                if len(value) != len(args):
                    raise TypeError(f"Argument '{arg_name}': expected tuple of length {len(args)}, got {len(value)}")
                for i, (item, sub) in enumerate(zip(value, args)):
                    _validate(item, sub, f"{arg_name}[{i}]")
            else:                                      # variable-length
                et = args[0] if args else Any
                for i, item in enumerate(value):
                    _validate(item, et, f"{arg_name}[{i}]")
        return

    # Concrete type
    if not isinstance(value, expected_type):
        raise TypeError(f"Argument '{arg_name}' expected {expected_type.__name__}, got {type(value).__name__}")


def validate_types(func=None, *, strict: bool = False):
    """Decorator that validates function arguments against their type hints.

    Parameters
    ----------
    func : callable, optional
        The function to wrap when used without parentheses.
    strict : bool, default False
        If *True*, also validate the return value.
    """
    def decorator(fn):
        hints = get_type_hints(fn)
        sig = inspect.signature(fn)

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            bound = sig.bind(*args, **kwargs)
            bound.apply_defaults()
            for name, val in bound.arguments.items():
                if name in hints:
                    _validate(val, hints[name], name)

            result = fn(*args, **kwargs)

            if strict and "return" in hints:
                _validate(result, hints["return"], "return")
            return result
        return wrapper

    if func is not None:
        return decorator(func)
    return decorator


