# sum_scores([90, "85", 92])      # ❌ TypeError: Argument 'scores[1]' expected int, got str


# 4. Dict with typed keys/values
@validate_types
def merge_config(cfg: dict[str, int]) -> str:
    return str(cfg)

print(merge_config({"port": 8080}))  # ✅ passes
# merge_config({"port": "8080"})      # ❌ TypeError: Argument 'cfg['port']' expected int, got str


# 5. Nested generics
@validate_types
def process(data: list[dict[str, Union[int, float]]]) -> int:
