import type { ParsedSkillBlock } from "../../../core/agent-session.js";
import { getMarkdownTheme, theme } from "../theme/theme.js";
import { editorKey } from "./keybinding-hints.js";

/**
 * Component that renders a skill invocation message with collapsed/expanded state.
 * Uses same background color as custom messages for visual consistency.
 */
export class SkillInvocationMessageComponent extends Box {
	private expanded = false;
	private skillBlock: ParsedSkillBlock;
	private markdownTheme: MarkdownTheme;

	constructor(skillBlock: ParsedSkillBlock, markdownTheme: MarkdownTheme = getMarkdownTheme()) {
		super(1, 1, (t) => theme.bg("customMessageBg", t));
		this.skillBlock = skillBlock;
		this.markdownTheme = markdownTheme;
		this.updateDisplay();
	}

	setExpanded(expanded: boolean): void {
		this.expanded = expanded;
		this.updateDisplay();
	}

	override invalidate(): void {
		super.invalidate();
		this.updateDisplay();
	}

	private updateDisplay(): void {
		this.clear();

		const label = theme.fg("customMessageLabel", `\x1b[1m[skill]\x1b[22m`);
		this.addChild(new Text(label, 0, 0));
		this.addChild(new Spacer(1));

		if (this.expanded) {
			// Show skill name and full content
			const header = `**${this.skillBlock.name}**\n\n`;
			this.addChild(
				new Markdown(header + this.skillBlock.content, 0, 0, this.markdownTheme, {
					color: (text: string) => theme.fg("customMessageText", text),
				}),
			);

			// Show user message if present
			if (this.skillBlock.userMessage) {
				this.addChild(new Spacer(1));
				this.addChild(
					new Markdown(this.skillBlock.userMessage, 1, 1, this.markdownTheme, {
						bgColor: (text: string) => theme.bg("userMessageBg", text),
						color: (text: string) => theme.fg("userMessageText", text),
					}),
				);
			}
		} else {
			// Collapsed view: show skill name and hint
			const collapsedText =
				theme.fg("customMessageText", `${this.skillBlock.name} (`) +
				theme.fg("dim", editorKey("expandTools")) +
				theme.fg("customMessageText", " to expand)");
			this.addChild(new Text(collapsedText, 0, 0));

			// Show user message preview if present
			if (this.skillBlock.userMessage) {
				this.addChild(new Spacer(1));
				this.addChild(
					new Markdown(this.skillBlock.userMessage, 1, 1, this.markdownTheme, {
						bgColor: (text: string) => theme.bg("userMessageBg", text),
						color: (text: string) => theme.fg("userMessageText", text),
					}),
				);
			}
		}
	}
}
