+export function resolveShellExecutionOptions(options?: ShellExecutionOptions): ResolvedShellExecutionOptions {
+	const shellConfig = getShellConfig();
+	const resolvedEnv = options?.env ? { ...options.env } : { ...getShellEnv() };
