@@
 function convertMessages(model: Model<"openai-codex-responses">, context: Context): unknown[] {
 	const messages: unknown[] = [];
+	const emittedCallIds = new Set<string>();
 	const transformed = transformMessages(context.messages, model);
+	const isFunctionCallItem = (item: unknown): item is { type: "function_call"; call_id: string } => {
+		if (!item || typeof item !== "object") return false;
+		const candidate = item as { type?: string; call_id?: string };
+		return candidate.type === "function_call" && typeof candidate.call_id === "string";
+	};
@@
-		} else if (msg.role === "assistant") {
-			messages.push(...convertAssistantMessage(msg));
+		} else if (msg.role === "assistant") {
+			const converted = convertAssistantMessage(msg);
+			for (const item of converted) {
+				if (isFunctionCallItem(item)) emittedCallIds.add(item.call_id);
+			}
+			messages.push(...converted);
 		} else if (msg.role === "toolResult") {
-			messages.push(...convertToolResult(msg, model));
+			const callId = msg.toolCallId.split("|")[0];
+			if (emittedCallIds.has(callId)) {
