import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Type } from "@sinclair/typebox";
import { Text } from "@mariozechner/pi-tui";

export default function (pi: ExtensionAPI) {
  const recentReads: { path: string; time: number }[] = [];
  const MAX_TRACKED = 20;

  // Track read tool calls
  pi.on("tool_call", async (event) => {
    if (event.toolName === "Read" && event.input.path) {
      recentReads.push({ path: event.input.path, time: Date.now() });
      if (recentReads.length > MAX_TRACKED) {
        recentReads.shift();
      }
    }
  });

  // Command to show recent reads
  pi.registerCommand("reads", {
    description: "Show recently read files",
    handler: async (_args, ctx) => {
      if (recentReads.length === 0) {
        ctx.ui.notify("No files read yet", "info");
        return;
      }
      const list = recentReads
        .slice()
        .reverse()
        .map((r) => {
          const ago = Math.round((Date.now() - r.time) / 1000);
          return `${r.path} (${ago}s ago)`;
        })
        .join("\n");
      ctx.ui.notify(`Recent reads:\n${list}`, "info");
    },
  });

  pi.registerTool({
    name: "greet",
    label: "Greet",
    description: "Says hi",
    parameters: Type.Object({}),
    async execute() {
      return {
        content: [{ type: "text", text: "hi" }],
        details: {},
      };
    },
    renderResult(_result, _options, theme) {
      const sparkles = "✨🎉👋🌟";
      const text = `${sparkles}\n${theme.fg("accent", theme.bold("  H E L L O !  "))}\n${sparkles}`;
      return new Text(text, 0, 0);
    },
  });
}

