{"path":"datavert/datavert.py","content":"#!/usr/bin/env python3
"""
datavert — CLI tool to convert between data formats (JSON, YAML, CSV, TOML, XML).

Usage examples:
    python datavert.py convert -i data.json -if json -of yaml
    echo '{"key": "value"}' | python datavert.py convert -if json -of yaml
    python datavert.py formats
"""

import argparse
import csv
import io
import json
import sys
from pathlib import Path

# ---------------------------------------------------------------------------
# Optional dependency handling
# ---------------------------------------------------------------------------

try:
    import yaml  # type: ignore
except ImportError:  # pragma: no cover
    yaml = None  # type: ignore

try:
    import toml as toml_lib  # type: ignore  # "toml" on PyPI
except ImportError:  # pragma: no cover
    try:
        import tomllib as toml_lib  # type: ignore  # Python 3.11+ stdlib (read only)
    except ImportError:
        toml_lib = None  # type: ignore

try:
    import xml.etree.ElementTree as ET  # always available
    from xml.dom import minidom
except ImportError:  # pragma: no cover
    ET = None  # type: ignore

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

FORMATS = ("json", "yaml", "csv", "toml", "xml")

# ---------------------------------------------------------------------------
# Parsers (input format → Python object)
# ---------------------------------------------------------------------------


def parse_json(text: str) -> object:
    """Parse a JSON string into a Python object."""
    return json.loads(text)


def parse_yaml(text: str) -> object:
    """Parse a YAML string into a Python object."""
    if yaml is None:
        _missing("PyYAML", "yaml")
    return yaml.safe_load(text)


def parse_csv(text: str) -> list[dict]:
    """Parse a CSV string into a list of dicts (one per row)."""
    reader = csv.DictReader(io.StringIO(text))
    return list(reader)


def parse_toml(text: str) -> dict:
    """Parse a TOML string into a Python dict."""
    if toml_lib is None:
        _missing("toml", "toml")
    return toml_lib.loads(text)


def parse_xml(text: str) -> dict | list:
    """Parse an XML string into a Python dict/list using a simple convention.

    Convention:
      <root>
        <item key="k1">v1</item>
        <item key="k2">v2</item>
      </root>
    → {"root": {"k1": "v1", "k2": "v2"}}

    Repeated sibling tags with the same name become a list.
    """
    root = ET.fromstring(text)
    return {root.tag: _xml_to_obj(root)}


def _xml_to_obj(element: "ET.Element") -> object:
    """Recursively convert an XML element to a Python object."""
    # If the element has a "key" attribute, treat it as a dict entry
    children = list(element)
    if not children and not element.attrib:
        # Leaf node — return text content
        return element.text or ""

    # Group children by tag
    groups: dict[str, list] = {}
    for child in children:
        groups.setdefault(child.tag, []).append(child)

    result: dict = {}
    for tag, elems in groups.items():
        converted = [_xml_to_obj(e) for e in elems]
        if len(converted) == 1:
            result[tag] = converted[0]
        else:
            result[tag] = converted

    # Merge any attributes as keys
    for k, v in element.attrib.items():
        result[k] = _auto_convert(v)

    return result


def _auto_convert(value: str) -> object:
    """Try to convert a string to int/float/bool, falling back to str."""
    if value.lower() in ("true", "false"):
        return value.lower() == "true"
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


# ---------------------------------------------------------------------------
# Serializers (Python object → output format string)
# ---------------------------------------------------------------------------


def serialize_json(obj: object) -> str:
    """Serialize a Python object to a pretty-printed JSON string."""
    return json.dumps(obj, indent=2, ensure_ascii=False)


def serialize_yaml(obj: object) -> str:
    """Serialize a Python object to a YAML string."""
    if yaml is None:
        _missing("PyYAML", "yaml")
    return yaml.dump(obj, default_flow_style=False, allow_unicode=True, sort_keys=False)


def serialize_csv(obj: object) -> str:
    """Serialize a Python object to a CSV string.

    Only lists of uniform dicts are supported.  Nested values are JSON-encoded.
    """
    if not isinstance(obj, list):
        raise ValueError("CSV output requires a list of flat dictionaries.")
    if not obj:
        return ""
    if not all(isinstance(row, dict) for row in obj):
        raise ValueError("CSV output requires a list of dictionaries.")

    # Flatten nested values to JSON strings
    flat_rows: list[dict] = []
    for row in obj:
        flat: dict = {}
        for k, v in row.items():
            flat[k] = v if isinstance(v, (str, int, float, bool)) and v is not None else json.dumps(v, ensure_ascii=False)
        flat_rows.append(flat)

    fieldnames = list(dict.fromkeys(k for row in flat_rows for k in row))
    buf = io.StringIO()
    writer = csv.DictWriter(buf, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(flat_rows)
    return buf.getvalue()


def serialize_toml(obj: object) -> str:
    """Serialize a Python dict to a TOML string."""
    if toml_lib is None:
        _missing("toml", "toml")
    if not isinstance(obj, dict):
        raise ValueError("TOML output requires a dictionary (table) at the top level.")
    return toml_lib.dumps(obj)


def serialize_xml(obj: object) -> str:
    """Serialize a Python dict to an XML string using a simple convention."""
    if not isinstance(obj, dict):
        raise ValueError("XML output requires a dictionary at the top level.")

    if len(obj) != 1:
        raise ValueError("XML output requires a single root key (e.g. {'root': ...}).")

    root_tag, root_data = next(iter(obj.items()))
    root_elem = ET.Element(root_tag)
    _obj_to_xml(root_data, root_elem)
    rough = ET.tostring(root_elem, encoding="unicode")
    pretty = minidom.parseString(rough).toprettyxml(indent="  ")
    # Remove the XML declaration line for a cleaner output
    lines = pretty.split("\n")
    if lines and lines[0].startswith("<?xml"):
        lines = lines[1:]
    return "\n".join(line for line in lines if line.strip())


def _obj_to_xml(data: object, parent: "ET.Element") -> None:
    """Recursively attach Python object data to an XML parent element."""
    if isinstance(data, dict):
        for key, value in data.items():
            child = ET.SubElement(parent, str(key))
            _obj_to_xml(value, child)
    elif isinstance(data, list):
        for item in data:
            child = ET.SubElement(parent, "item")
            _obj_to_xml(item, child)
    else:
        parent.text = str(data)


# ---------------------------------------------------------------------------
# Dispatch tables
# ---------------------------------------------------------------------------

PARSERS = {
    "json": parse_json,
    "yaml": parse_yaml,
    "csv": parse_csv,
    "toml": parse_toml,
    "xml": parse_xml,
}

SERIALIZERS = {
    "json": serialize_json,
    "yaml": serialize_yaml,
    "csv": serialize_csv,
    "toml": serialize_toml,
    "xml": serialize_xml,
}

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _missing(package: str, fmt: str) -> None:
    """Print a helpful error and exit when an optional dep is missing."""
    print(
        f"Error: The '{fmt}' format requires the '{package}' package.\n"
        f"Install it with:  pip install {package}",
        file=sys.stderr,
    )
    sys.exit(1)


def detect_format(path: str) -> str | None:
    """Guess the format from a file extension."""
    ext = Path(path).suffix.lower().lstrip(".")
    mapping = {
        "json": "json",
        "yml": "yaml",
        "yaml": "yaml",
        "csv": "csv",
        "toml": "toml",
        "xml": "xml",
    }
    return mapping.get(ext)


# ---------------------------------------------------------------------------
# Sub-commands
# ---------------------------------------------------------------------------


def cmd_convert(args: argparse.Namespace) -> None:
    """Read input, parse, serialize to output format, and write."""
    input_fmt = args.input_format
    output_fmt = args.output_format

    # Read source text
    if args.input:
        source = Path(args.input)
        if not source.exists():
            print(f"Error: input file not found: {source}", file=sys.stderr)
            sys.exit(1)
        text = source.read_text(encoding="utf-8")
        # Auto-detect format if not specified
        if input_fmt is None:
            input_fmt = detect_format(str(source))
            if input_fmt is None:
                print(
                    f"Error: cannot detect format from extension '{source.suffix}'. "
                    "Use -if/--input-format to specify.",
                    file=sys.stderr,
                )
                sys.exit(1)
    else:
        if input_fmt is None:
            print(
                "Error: --input-format is required when reading from stdin.",
                file=sys.stderr,
            )
            sys.exit(1)
        text = sys.stdin.read()

    # Parse
    try:
        data = PARSERS[input_fmt](text)
    except Exception as exc:
        print(f"Error parsing input as {input_fmt}: {exc}", file=sys.stderr)
        sys.exit(1)

    # Serialize
    try:
        result = SERIALIZERS[output_fmt](data)
    except (ValueError, TypeError) as exc:
        print(f"Error serializing to {output_fmt}: {exc}", file=sys.stderr)
        sys.exit(1)

    # Write output
    if args.output:
        Path(args.output).write_text(result, encoding="utf-8")
        print(f"✓ Wrote {args.output}", file=sys.stderr)
    else:
        sys.stdout.write(result)
        if not result.endswith("\n"):
            sys.stdout.write("\n")


def cmd_formats(_args: argparse.Namespace) -> None:
    """List all supported formats and their status."""
    print("Supported formats:\n")
    fmt_info = [
        ("json", "Always available", "Always available"),
        ("yaml", "Requires PyYAML" + (" ✓" if yaml else " ✗"), "Requires PyYAML" + (" ✓" if yaml else " ✗")),
        ("csv", "Always available", "Always available"),
        ("toml", "Requires toml lib" + (" ✓" if toml_lib else " ✗"), "Requires toml lib" + (" ✓" if toml_lib else " ✗")),
        ("xml", "Always available", "Always available"),
    ]
    col = max(len(r[0]) for r in fmt_info) + 2
    for name, read_status, write_status in fmt_info:
        print(f"  {name:<{col}} read: {read_status:<25} write: {write_status}")
    print()


# ---------------------------------------------------------------------------
# Argument parser
# ---------------------------------------------------------------------------


def build_parser() -> argparse.ArgumentParser:
    """Construct and return the argument parser."""
    parser = argparse.ArgumentParser(
        prog="datavert",
        description="Convert between data formats: JSON, YAML, CSV, TOML, XML.",
        epilog="Examples:\n"
        "  datavert convert -i data.json -if json -of yaml\n"
        "  echo '[1,2,3]' | datavert convert -if json -of yaml\n"
        "  datavert formats\n",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    subparsers = parser.add_subparsers(dest="command", help="Available commands")

    # ---- convert ----
    conv = subparsers.add_parser(
        "convert",
        help="Convert between data formats",
        description="Read data in one format and write it in another.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=(
            "Examples:\n"
            "  datavert convert -i data.json -if json -of yaml\n"
            "  cat config.yaml | datavert convert -if yaml -of json\n"
            "  datavert convert -i records.csv -if csv -of json -o records.json\n"
        ),
    )
    conv.add_argument(
        "-i", "--input",
        help="Path to input file (omit to read from stdin)",
        default=None,
    )
    conv.add_argument(
        "-if", "--input-format",
        choices=FORMATS,
        help="Input format (auto-detected from file extension when using -i)",
        default=None,
    )
    conv.add_argument(
        "-of", "--output-format",
        choices=FORMATS,
        required=True,
        help="Output format",
    )
    conv.add_argument(
        "-o", "--output",
        help="Path to output file (omit to write to stdout)",
        default=None,
    )
    conv.set_defaults(func=cmd_convert)

    # ---- formats ----
    fmts = subparsers.add_parser(
        "formats",
        help="List supported formats",
        description="Show all supported data formats and library availability.",
    )
    fmts.set_defaults(func=cmd_formats)

    return parser


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def main(argv: list[str] | None = None) -> None:
    """Main entry point."""
    parser = build_parser()
    args = parser.parse_args(argv)

    if args.command is None:
        parser.print_help()
        sys.exit(0)

    args.func(args)


if __name__ == "__main__":
    main()
"}

