from __future__ import annotations

import time
from dataclasses import dataclass
from typing import Optional


@dataclass
class RateLimitResult:
    """Result of a rate-limit check."""

    allowed: bool
    tokens_remaining: float
    capacity: float
    retry_after: float = 0.0


class TokenBucket:
    """
    In-memory token bucket rate limiter.

    Thread safety is the responsibility of the storage backend in multi-threaded
    or distributed use cases. This class implements the pure algorithm.
    """

    def __init__(self, capacity: float, refill_rate: float, current_tokens: Optional[float] = None) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate <= 0:
            raise ValueError("refill_rate must be positive")

        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self.tokens = float(current_tokens if current_tokens is not None else capacity)
        if not (0 <= self.tokens <= self.capacity):
            raise ValueError("current_tokens must be between 0 and capacity")
        self.last_refill = time.monotonic()

    def _refill(self) -> None:
        now = time.monotonic()
        elapsed = now - self.last_refill
        if elapsed > 0:
            self.tokens = min(self.capacity, self.tokens + elapsed * self.refill_rate)
            self.last_refill = now

    def allow(self, tokens: float = 1.0) -> RateLimitResult:
        """Request `tokens` from the bucket.

        Returns a RateLimitResult indicating whether the request is allowed
        and how long the caller should wait before retrying if denied.
        """
        if tokens <= 0:
            raise ValueError("tokens must be positive")
        if tokens > self.capacity:
            raise ValueError("request exceeds bucket capacity")

        self._refill()
        if self.tokens >= tokens:
            self.tokens -= tokens
            return RateLimitResult(
                allowed=True,
                tokens_remaining=self.tokens,
                capacity=self.capacity,
                retry_after=0.0,
            )

        deficit = tokens - self.tokens
        retry_after = deficit / self.refill_rate
        return RateLimitResult(
            allowed=False,
            tokens_remaining=self.tokens,
            capacity=self.capacity,
            retry_after=retry_after,
        )
