# ── Filter interface ──────────────────────
def filter(self, record: logging.LogRecord) -> bool:
    # 1. Pre-format the message (msg % args) so we redact the
    #    *final* text, not the template.  This avoids removing
    #    %s placeholders that would break getMessage() later.
    if record.args:
        try:
            formatted_msg = str(record.msg) % record.args
        except (TypeError, ValueError):
            # Fallback: redact msg and args independently
            formatted_msg = self._redact(str(record.msg))
            if isinstance(record.args, dict):
                formatted_msg = formatted_msg % {
                    k: self._redact(str(v)) if isinstance(v, str) else v
                    for k, v in record.args.items()
                }
            elif isinstance(record.args, tuple):
                formatted_msg = formatted_msg % tuple(
                    self._redact(str(a)) if isinstance(a, str) else a
                    for a in record.args
                )
        record.msg = self._redact(formatted_msg)
        record.args = None
    else:
        record.msg = self._redact(str(record.msg))

    # 2. Redact any extra record attributes the user opted into
    for key in self.extra_keys:
        value = getattr(record, key, None)
        if isinstance(value, str):
            setattr(record, key, self._redact(value))

    # 3. Always return True — we never *block* the record,
    #    we only sanitise it.
    return True

