{"path":"daily_summary/loader.py","content":""""
Load data from configured sources into pandas DataFrames.
Supports CSV for now; easily extensible to DB / API sources.
"""

import os
import pandas as pd
from config import DATA_SOURCES


def load_source(name: str, cfg: dict) -> pd.DataFrame:
    """Load a single data source and ensure the date column is parsed."""
    source_type = cfg.get("type", "csv")

    if source_type == "csv":
        path = cfg["path"]
        if not os.path.exists(path):
            raise FileNotFoundError(f"Data file not found: {path}")
        df = pd.read_csv(path, parse_dates=[cfg["date_column"]])
    else:
        raise ValueError(f"Unsupported source type: {source_type}")

    return df


def load_all() -> dict[str, pd.DataFrame]:
    """Load every configured data source. Returns {name: DataFrame}."""
    frames = {}
    for name, cfg in DATA_SOURCES.items():
        frames[name] = load_source(name, cfg)
        print(f"  ✔ Loaded '{name}': {len(frames[name]):,} rows")
    return frames
"}

