{"path":"redis_api_cache/config.py","content":""""Configuration dataclass for the Redis caching layer."""

from __future__ import annotations

import dataclasses
import os
from typing import Optional


@dataclasses.dataclass
class CacheConfig:
    """All tuneable parameters for the Redis cache.

    Every field can also be set via an environment variable (upper-cased
    and prefixed with ``REDIS_CACHE_``, e.g. ``REDIS_CACHE_URL``).

    Attributes:
        url:            Redis connection URL (redis://host:port/db).
        default_ttl:    Fallback TTL in seconds when none is specified.
        key_prefix:     String prepended to every Redis key.
        compress_min:   Compress values larger than this many bytes (0 = off).
        connect_timeout: Socket connect timeout in seconds.
        socket_timeout:  Socket read/write timeout in seconds.
        max_retries:    Connection retries before giving up.
        retry_backoff:  Exponential backoff base (seconds) between retries.
        graceful_errors: If True, swallow Redis errors and return miss.
        lock_timeout:   Seconds to hold a stampede-protection lock.
        stats_enabled:  Track hit / miss / error counters.
    """

    url: str = "redis://localhost:6379/0"
    default_ttl: int = 300          # 5 minutes
    key_prefix: str = "api_cache:"
    compress_min: int = 1024        # bytes; 0 disables compression
    connect_timeout: float = 3.0
    socket_timeout: float = 2.0
    max_retries: int = 3
    retry_backoff: float = 0.5
    graceful_errors: bool = True
    lock_timeout: int = 30
    stats_enabled: bool = True

    # ------------------------------------------------------------------
    # Convenience constructors
    # ------------------------------------------------------------------
    @classmethod
    def from_env(cls, prefix: str = "REDIS_CACHE_") -> "CacheConfig":
        """Build a ``CacheConfig`` from environment variables.

        Example environment variable mapping::

            REDIS_CACHE_URL=redis://redis:6379/1
            REDIS_CACHE_DEFAULT_TTL=600
        """
        fields = {f.name for f in dataclasses.fields(cls)}
        kwargs: dict = {}
        for key, value in os.environ.items():
            if key.startswith(prefix):
                attr = key[len(prefix) :].lower()
                if attr in fields:
                    kwargs[attr] = _cast(attr, value, cls)
        return cls(**kwargs)

    @classmethod
    def from_dict(cls, d: dict) -> "CacheConfig":
        """Build a ``CacheConfig`` from a plain dictionary (ignores unknown keys)."""
        fields = {f.name for f in dataclasses.fields(cls)}
        return cls(**{k: v for k, v in d.items() if k in fields})


# ------------------------------------------------------------------
# Helpers
# ------------------------------------------------------------------

def _cast(name: str, value: str, cls: type) -> object:
    """Cast a string value to the type expected by *cls* for *name*."""
    field_type = {f.name: f.type for f in dataclasses.fields(cls)}[name]
    type_map = {"int": int, "float": float, "str": str, "bool": _to_bool}
    for type_name, caster in type_map.items():
        if field_type == type_name:
            return caster(value)
    return value


def _to_bool(value: str) -> bool:
    return value.lower() in ("1", "true", "yes", "on")
"}

{"path":"redis_api_cache/serializers.py","content":""""Serialisation helpers: JSON with optional gzip compression."""

from __future__ import annotations

import gzip
import json
from typing import Any


# ------------------------------------------------------------------
# Public API
# ------------------------------------------------------------------

def serialize(value: Any, compress_min: int = 1024) -> tuple[bytes, bool]:
    """Serialise *value* to bytes.

    Returns
    -------
    (payload, compressed)
        *payload* is always ``bytes``.  *compressed* is ``True`` when the
        result was gzip-compressed (because the raw JSON exceeded
        *compress_min* bytes).
    """
    raw = json.dumps(value, separators=(",", ":"), default=_json_default).encode("utf-8")
    if compress_min and len(raw) >= compress_min:
        return gzip.compress(raw), True
    return raw, False


def deserialize(payload: bytes, compressed: bool) -> Any:
    """Reverse :func:`serialize`."""
    raw = gzip.decompress(payload) if compressed else payload
    return json.loads(raw)


# ------------------------------------------------------------------
# Internals
# ------------------------------------------------------------------

def _json_default(obj: Any) -> Any:
    """Fallback serialiser for non-standard types."""
    # Handle common types that json.dumps can't handle by default
    if isinstance(obj, (set, frozenset)):
        return list(obj)
    if isinstance(obj, bytes):
        return obj.decode("utf-8", errors="replace")
    if hasattr(obj, "isoformat"):  # datetime, date, time
        return obj.isoformat()
    if hasattr(obj, "__float__"):
        return float(obj)
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serialisable")
"}

